/* MailerLite, Brevo and Flodesk for a OnePage's signups (round 41, run after `315`): the `onepage_integrations` provider check takes 'mailerlite', 'brevo' and 'flodesk' beside Mailchimp, Kit, beehiiv, Zapier, Make, Google Sheets and a webhook. The check made by part 315 (named onepage_integrations_provider_check by Postgres) is dropped and added again NOT VALID, then validated, so the table is never locked against writes while old rows are read; every row already there holds one of the old seven and passes. One constraint changes; no row, column, grant or policy does. Until it runs, connecting one of the three says this part is needed and the other tools work as before. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.onepage_integrations') IS NULL THEN RAISE NOTICE 'part 323: run part 315 first.'; RETURN; END IF; ALTER TABLE public.onepage_integrations DROP CONSTRAINT IF EXISTS onepage_integrations_provider_check; ALTER TABLE public.onepage_integrations ADD CONSTRAINT onepage_integrations_provider_check CHECK (provider IN ('mailchimp', 'kit', 'beehiiv', 'mailerlite', 'brevo', 'flodesk', 'zapier', 'make', 'sheets', 'webhook')) NOT VALID; ALTER TABLE public.onepage_integrations VALIDATE CONSTRAINT onepage_integrations_provider_check; END $do$;
notify pgrst, 'reload schema';
